styles:
.map_card {
  background: #ffffff;
  transition: background-color 0.2s ease;
  cursor: pointer;
}

.map_card.is-active {
  background: #e8ceff;
}

#map {
  position: relative;
}

.map_static_wrap {
  position: absolute;
  inset: 0;
  z-index: 5;
  overflow: hidden;
  background: #d9d9d9;
}

.map_static_img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.map_load_btn {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 6;
  border: 0;
  border-radius: 999px;
  padding: 14px 22px;
  cursor: pointer;
  background: #e8ceff;
  color: #121214;
  font:
    600 15px/1.2 system-ui,
    -apple-system,
    sans-serif;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

.mapboxgl-popup-content,
.mapboxgl-popup-content * {
  font-family: inherit;
}

.mapboxgl-popup-content {
  border-radius: 12px;
  padding: 12px 14px;
  min-width: 250px;
}

.popup-title {
  font-size: 18px;
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: 6px;
}

.popup-address,
.popup-hours {
  font-size: 14px;
  line-height: 1.35;
  margin-bottom: 4px;
}

.popup-meta {
  margin-top: 8px;
  display: grid;
  gap: 6px;
}

.popup-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  line-height: 1.2;
}

.popup-meta-row img {
  width: 18px;
  height: 18px;
  object-fit: contain;
  flex: 0 0 18px;
}

